// Reload: clear and re-init
When('the app is reloaded', function () {
  // Capture current localStorage before dispose
  const data = this.localStorage.getItem('todos-vanilla');
  this.disposeApp();
  // Create a temp window to stage localStorage, then feed it to loadApp
  // loadApp creates its own window, so we set data on that window after creation
  // but before app.js eval by overriding loadApp with a one-off sequence
  const fs = require('node:fs');
  const path = require('node:path');
  const { Window } = require('happy-dom');
  const ROOT = path.resolve(__dirname, '..', '..');
  const indexPath = path.join(ROOT, 'index.html');
  const appPath = path.join(ROOT, 'js', 'app.js');

  this.window = new Window({
    url: 'http://localhost/',
    settings: { disableJavaScriptFileLoading: true },
  });
  this.document = this.window.document;

  // Set localStorage BEFORE eval so the store reads persisted data on init
  if (data !== null) {
    this.localStorage.setItem('todos-vanilla', data);
  }

  this.document.write(fs.readFileSync(indexPath, 'utf8'));
  this.document.close();
  this.window.eval(fs.readFileSync(appPath, 'utf8'));
  this.document.dispatchEvent(new this.window.Event('DOMContentLoaded', { bubbles: true }));
  this.window.dispatchEvent(new this.window.Event('load'));

  // Re-attach hash routing proxy
  const w = this.window;
  this.document.addEventListener('click', function (e) {
    const a = e.target && e.target.closest ? e.target.closest('a[href^="#"]') : null;
    if (!a) return;
    const next = a.getAttribute('href');
    if (w.location.hash !== next) { w.location.hash = next; w.dispatchEvent(new w.Event('hashchange')); }
  }, true);

  // Reset input and trigger initial render from persisted state
  this.document.querySelector('.new-todo').value = '';
  this.window.location.hash = '';
  this.window.dispatchEvent(new this.window.Event('hashchange'));
});

