  this.navigate(hash);
});
```

And `this.navigate('#/active')` dispatches hashchange. The app's hashchange handler processes it and calls `route('active')`.

But wait - the world.js also has a click listener:
```javascript
this.document.addEventListener('click', function (e) {
    const a = e.target && e.target.closest ? e.target.closest('a[href^="#"]') : null;
